-- Sample testimonial 1 (data-analytics)
insert into public.testimonials (name, role, organization, course_id, quote, rating, is_published, sort_order)
select r.name, r.role, r.organization, (select id from public.courses where slug = 'data-analytics'), r.quote, r.rating, false, r.sort_order
from jsonb_populate_record(null::public.testimonials, convert_from(decode('', 'base64'), 'UTF8')::jsonb) r
where not exists (select 1 from public.testimonials x where x.quote = r.quote);

